erencia</b><br><?=e($r['referencia_revision']?:'—')?></div><div class="dato"><b>Base de precios</b><br><?=e($r['lista_nombre']?:'Base histórica no identificada')?><?=!empty($r['lista_fecha_archivo'])?' · '.e($r['lista_fecha_archivo']):''?></div><div class="dato"><b>Estado</b><br><?=e($r['estado'])?></div><div class="dato"><b>Responsable comercial</b><br><?=e($r['responsable']?:'—')?></div><div class="dato"><b>Fecha de esta versión</b><br><?=e(fechaHoraAr($fechaVersionHistorica))?></div><div class="dato" style="grid-column:1/-1"><b>Motivo de modificación</b><br><?=nl2br(e($motivoVersion))?></div></div><div class="tabla-wrap"><table><tr><th>Módulo</th><th>Concepto</th><th>Código</th><th>Descripción</th><th>Cantidad</th><th>Unitario</th><th>Fórmula</th><th>Total</th></tr><?php while($x=$d->fetch_assoc()):?><tr><td><?=e($x['modulo'])?></td><td><?=e($x['concepto'])?></td><td><?=e($x['codigo'])?></td><td><?=e($x['descripcion'])?></td><td><?=number_format((float)$x['cantidad'],2,',','.')?></td><td>$<?=number_format(ceil((float)$x['precio_unitario']),0,',','.')?></td><td><?=e($x['formula_aplicada'])?></td><td>$<?=number_format(ceil((float)$x['importe_total']),0,',','.')?></td></tr><?php endwhile;?></table></div><div class="total"><b>Total histórico: $<?=number_format(ceil((float)$r['total']),0,',','.')?></b></div></main></body></html>
